function renderList(){const q=fold($('#search').value.trim()),filter=$('#system-filter').value;let html='',count=0;for(const [cat,name] of Object.entries(categories)){const list=parts.filter(p=>(filter==='all'||filter===cat)&&p.cat===cat&&(!state.onlyMoving||p.motion)&&fold(p.name+' '+p.description+' '+p.how+' '+name).includes(q));if(!list.length)continue;count+=list.length;html+=`<div class="category-heading">${name}<span>${list.length}</span></div>`+list.map(p=>{const s=saved.checks[p.id];return`<button class="part-item ${p.id===state.selected?'active':''}" data-part="${p.id}" aria-pressed="${p.id===state.selected}"><span class="part-num">${String(p.index).padStart(3,'0')}</span><span>${p.name}</span>${p.motion?'<span class="motion-indicator" title="Ma mechanizm">◇</span>':''}<i class="part-dot ${s==='ok'?'ok':s==='concern'?'concern':saved.seen.includes(p.id)?'seen':''}"></i></button>`;}).join('');}$('#part-list').innerHTML=html||'<p class="empty-list">Brak pasujących części. Spróbuj np. „zawór”, „przepustnica” lub „piasta”.</p>';$('#list-count').textContent=`${count} / ${parts.length}`;$('#only-moving').setAttribute('aria-pressed',String(state.onlyMoving));$('#export').hidden=state.tab!=='notes';}
