function setView(name){if(name==='under')setMode('chassis',false);groundVisible(name!=='under');tween(...presets[name]);$('#view-name').textContent={perspective:'PERSPEKTYWA ¾',front:'WIDOK Z PRZODU',side:'WIDOK Z BOKU',rear:'WIDOK Z TYŁU',top:'WIDOK Z GÓRY',under:'WIDOK PODWOZIA'}[name];$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));}
