const note=$('#mode-note');note.hidden=mode==='body';note.textContent={engine:'Osprzęt R4 2.0 MPI. Osłona dekoracyjna jest odsunięta w przekroju.',internals:'Cykl 4-suwowy · 720°. Animacja spowolniona; kształty krzywek i fazy są uproszczone.',cabin:'Dach i szyby górne ukryto. Każde drzwi, okno i fotel mają własne sterowanie.',chassis:'Przekrój od spodu. Opony i felgi ukryto, aby odsłonić hamulce.'}[mode]||'';
$('#view-name').textContent={body:'PERSPEKTYWA ¾',engine:'KOMORA SILNIKA',internals:'R4 · PRZEKRÓJ MECHANIZMU',cabin:'KABINA I BAGAŻNIK',chassis:'PODWOZIE I INSTALACJE'}[mode];
$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode));});$$('[data-view]').forEach(b=>b.classList.toggle('active',mode==='body'&&b.dataset.view==='perspective'));
