function syncVisibility(){const allowed=state.isolate?model.descendants(state.selected):null,selected=state.selected;
const cut=new Set(['engine-cover','cam-cover','head','block','oil-pan','timing-cover','intake','fuel-rail','coil-1','coil-2','coil-3','coil-4','gearbox']);
for(const c of Object.values(model.registry)){
const p=byId[c.id];let visible=true,opacity=null;
if(state.mode==='engine'&&c.id==='engine-cover'&&selected!==c.id)visible=false;
if(state.mode==='internals'){visible=p.cat==='internals'||['timing-belt','spark-1','spark-2','spark-3','spark-4','flywheel'].includes(c.id);if(cut.has(c.id))visible=false;}
if(state.mode==='cabin'){if(c.roof||['roof','windshield','rear-glass'].includes(c.id))visible=false;if(c.id==='structure')opacity=.18;}
if(state.mode==='chassis'){if(p.cat==='body')opacity=c.glass?.025:.07;if(p.cat==='cabin')visible=false;if(c.id.startsWith('tire-')||c.id.startsWith('rim-'))visible=false;if(['clutch','flywheel','differential'].includes(selected)&&c.id==='gearbox')visible=false;}
if(state.xray&&p.cat==='body')opacity=c.glass?.04:.11;
if(c.id===selected){visible=true;opacity=null;}
if(allowed)visible=allowed.has(c.id);
c.visual.visible=visible;
for(const m of c.materials.values()){const o=opacity===null?m.userData.baseOpacity:opacity;m.opacity=o;const transparent=o<1||m.userData.baseTransparent;if(m.transparent!==transparent){m.transparent=transparent;m.needsUpdate=true;}m.depthWrite=o>.35&&!c.glass;if(m.emissive&&m.userData.baseEmissive&&!['light','tail','climate'].includes(c.control?.kind))m.emissive.copy(m.userData.baseEmissive);}
}
$$('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===state.mode)));groundVisible(!state.isolate&&!['chassis','internals'].includes(state.mode));$('#isolation-tag').hidden=!state.isolate;$('#labels-toggle').setAttribute('aria-pressed',String(state.labels));$('#xray-toggle').setAttribute('aria-pressed',String(state.xray));}
function focusPart(id,anticipate=false){if(!ready)return;const c=model.registry[id],point=model.point(id),set=state.isolate?model.descendants(id):new Set([id]),bounds=new T.Box3();for(const child of set)bounds.union(new T.Box3().setFromObject(model.registry[child].visual));const sphere=bounds.getBoundingSphere(new T.Sphere()),r=clamp(sphere.radius,.035,3);
if(anticipate){const delta=c.detachTarget-c.detach;point.add(c.dir.clone().multiplyScalar(delta).applyQuaternion(c.frame.getWorldQuaternion(new T.Quaternion())));}
const cat=byId[id].cat,side=c.anchor.z<-.1?-1:1;let yaw=side*1.10,pitch=1.05;
if(cat==='engine'){yaw=side*.87;pitch=.72;}if(cat==='internals'){yaw=side*1.05;pitch=1.0;}if(cat==='fuel'||cat==='chassis'){pitch=2.05;groundVisible(false);}if(id==='trunk'||id==='rear-glass'){yaw=Math.PI-.55;pitch=1.08;}const distance=state.isolate?clamp(r*3.5,.30,9):clamp(r*4.2,.85,6.8);tween(yaw,pitch,distance,point);}
$$('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#labels-toggle').onclick=()=>{state.labels=!state.labels;syncVisibility();};$('#xray-toggle').onclick=()=>{state.xray=!state.xray;syncVisibility();};$('#leave-isolation').onclick=()=>{state.isolate=false;syncVisibility();renderDetail();focusPart(state.selected);};
$('#reset').onclick=()=>{model.reset();state.explosion=0;state.xray=false;$('#explode').value='0';setMode('body');toast('Złożono model i przywrócono widok.');};$('#explode').oninput=e=>state.explosion=Number(e.target.value)/100;$('#engine-run').onclick=()=>{model.globals.engine=!model.globals.engine;renderDetail();};$('#cycle-angle').oninput=e=>{model.globals.engine=false;model.globals.phase=Number(e.target.value)/720*Math.PI*4;};
$$('[data-paint]').forEach(b=>b.onclick=()=>{model.setPaint(b.dataset.paint);$$('[data-paint]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});});$('#studio-light').onchange=e=>studio.setLight(e.target.value);
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(stage.requestFullscreen)await stage.requestFullscreen();else toast('Pełny ekran jest niedostępny w tej przeglądarce.');}catch(e){toast('Nie udało się włączyć pełnego ekranu.');}};
const pointers=new Map();let gesture=null,start=null,dragged=false;
function begin(){const p=[...pointers.values()];gesture=p.length>1?{x:(p[0].x+p[1].x)/2,y:(p[0].y+p[1].y)/2,d:Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)}:p.length?{x:p[0].x,y:p[0].y,button:p[0].button}:null;}
