function hit(x,y){const r=canvas.getBoundingClientRect();mouse.set((x-r.left)/r.width*2-1,-(y-r.top)/r.height*2+1);ray.setFromCamera(mouse,camera);const hits=ray.intersectObjects(model.meshes,false).filter(h=>visible(h.object));return hits.find(h=>h.object.material.opacity>.27&&!model.registry[h.object.userData.part].glass)||hits[0];}
canvas.onpointerdown=e=>{if(e.button!==0&&e.button!==2)return;cameraTween=null;canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY,button:e.button});if(pointers.size===1){start={x:e.clientX,y:e.clientY};dragged=false;}else dragged=true;begin();$('#tooltip').hidden=true;};
canvas.onpointermove=e=>{if(pointers.has(e.pointerId)){pointers.set(e.pointerId,{x:e.clientX,y:e.clientY,button:e.button});if(start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)>5)dragged=true;const p=[...pointers.values()];if(p.length===1&&gesture){const dx=p[0].x-gesture.x,dy=p[0].y-gesture.y;if(gesture.button===2||e.shiftKey)pan(dx,dy);else{orbit.yaw-=dx*.006;orbit.pitch=clamp(orbit.pitch+dy*.006,.06,2.85);}}else if(p.length>1&&gesture?.d){const d=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);orbit.distance=clamp(orbit.distance*gesture.d/Math.max(d,20),.22,16);pan((p[0].x+p[1].x)/2-gesture.x,(p[0].y+p[1].y)/2-gesture.y);}begin();updateCamera();}else if(e.pointerType==='mouse'&&performance.now()-lastHover>90){lastHover=performance.now();const h=hit(e.clientX,e.clientY),tip=$('#tooltip');canvas.style.cursor=h?'pointer':'grab';tip.hidden=!h;if(h){const r=stage.getBoundingClientRect();tip.textContent=byId[h.object.userData.part].name;tip.style.left=clamp(e.clientX-r.left+13,8,r.width-190)+'px';tip.style.top=clamp(e.clientY-r.top+15,40,r.height-110)+'px';}}};
canvas.onpointerup=e=>{const has=pointers.has(e.pointerId);pointers.delete(e.pointerId);if(has&&!dragged&&e.button===0&&pointers.size===0){const h=hit(e.clientX,e.clientY);if(h)selectPart(h.object.userData.part,false,false);}begin();};canvas.onpointercancel=e=>{pointers.delete(e.pointerId);dragged=true;begin();};canvas.onpointerleave=()=>$('#tooltip').hidden=true;canvas.oncontextmenu=e=>e.preventDefault();canvas.addEventListener('wheel',e=>{e.preventDefault();cameraTween=null;orbit.distance=clamp(orbit.distance*Math.exp(clamp(e.deltaY,-100,100)*.0015),.22,16);updateCamera();},{passive:false});
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||e.ctrlKey||e.metaKey||e.altKey||e.repeat||$('dialog[open]'))return;const k=e.key.toLowerCase();if(k==='/'){e.preventDefault();$('#search').focus();}if(k==='r')$('#reset').click();if(k==='h')model.setControl('hood',model.controlValue('hood')>.5?0:1);if(k==='b')model.setControl('trunk',model.controlValue('trunk')>.5?0:1);if(k==='d'){const open=model.controlValue('door-lf')>.5?0:1;for(const id of ['door-lf','door-rf','door-lb','door-rb'])model.setControl(id,open);}if('12345'.includes(k)&&k.length===1)setMode(['body','engine','internals','cabin','chassis'][Number(k)-1]);if(e.target===canvas&&['arrowleft','arrowright','arrowup','arrowdown','+','-','='].includes(k)){e.preventDefault();cameraTween=null;if(k==='arrowleft')orbit.yaw-=.10;if(k==='arrowright')orbit.yaw+=.10;if(k==='arrowup')orbit.pitch=clamp(orbit.pitch-.10,.06,2.85);if(k==='arrowdown')orbit.pitch=clamp(orbit.pitch+.10,.06,2.85);if(k==='+'||k==='=')orbit.distance=Math.max(.22,orbit.distance*.9);if(k==='-')orbit.distance=Math.min(16,orbit.distance*1.1);}});
const markerNodes={};for(const p of parts){const b=document.createElement('button');b.className='marker';b.hidden=true;b.style.display='none';b.setAttribute('aria-label',p.name);b.innerHTML=`<span class="marker-dot">${p.index}</span><span class="marker-label">${p.name}</span>`;b.onclick=()=>selectPart(p.id,false,false);$('#markers').append(b);markerNodes[p.id]=b;}
const markerRay=new T.Raycaster();function markers(){const w=stage.clientWidth,h=stage.clientHeight,placed=[];for(const b of Object.values(markerNodes)){b.hidden=true;b.style.display='none';}if(!state.labels)return;
const items=parts.filter(p=>{if(!model.registry[p.id].visual.visible)return false;if(p.id===state.selected)return true;if(state.mode==='body')return p.cat==='body';if(state.mode==='chassis')return ['chassis','fuel'].includes(p.cat);return p.cat===state.mode;}).map(p=>({p,point:model.point(p.id)}));items.sort((a,b)=>(b.p.id===state.selected)-(a.p.id===state.selected)||a.point.distanceToSquared(camera.position)-b.point.distanceToSquared(camera.position));
for(const {p,point} of items){if(placed.length>=12)break;const v=point.clone().project(camera),x=(v.x*.5+.5)*w,y=(-v.y*.5+.5)*h;if(v.z<-1||v.z>1||x<20||x>w-20||y<112||y>h-140||placed.some(a=>Math.hypot(x-a[0],y-a[1])<47))continue;const d=point.clone().sub(camera.position),len=d.length();markerRay.set(camera.position,d.normalize());markerRay.far=Math.max(0,len-.035);const occluder=markerRay.intersectObjects(model.meshes,false).find(t=>t.object.userData.part!==p.id&&visible(t.object)&&t.object.material.opacity>.35&&!model.registry[t.object.userData.part].glass);if(occluder)continue;const b=markerNodes[p.id];b.hidden=false;b.style.display='flex';b.style.left=x+'px';b.style.top=y+'px';b.classList.toggle('active',p.id===state.selected);placed.push([x,y]);}}
function resize(){renderer.setSize(stage.clientWidth,stage.clientHeight,false);camera.aspect=stage.clientWidth/stage.clientHeight;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(stage);resize();
let last=performance.now(),infoLast=0;function animate(now){requestAnimationFrame(animate);const dt=Math.min((now-last)/1000,.05);last=now;if(cameraTween){const c=cameraTween,t=c.duration?clamp((now-c.start)/c.duration,0,1):1,e=t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;orbit.yaw=T.MathUtils.lerp(c.from.yaw,c.to.yaw,e);orbit.pitch=T.MathUtils.lerp(c.from.pitch,c.to.pitch,e);orbit.distance=T.MathUtils.lerp(c.from.distance,c.to.distance,e);orbit.target.lerpVectors(c.from.target,c.to.target,e);if(t===1)cameraTween=null;}model.step(dt,now/1000,state.explosion);updateCamera();if(frame++%8===0)markers();if(now-infoLast>120){infoLast=now;const angle=model.globals.phase/(Math.PI*4)*720;$('#engine-run').textContent=model.globals.engine?'Ⅱ Zatrzymaj mechanizm':'▶ Uruchom mechanizm';$('#engine-run').setAttribute('aria-pressed',String(model.globals.engine));if(document.activeElement!==$('#cycle-angle'))$('#cycle-angle').value=String(Math.round(angle));$('#cycle-label').textContent=`${Math.round(angle)}° · ${['dolot','sprężanie','praca','wydech'][Math.min(3,Math.floor(angle/180))]} cylindra 1`;}
renderer.render(scene,camera);}
ready=true;syncVisibility();renderDetail();model.step(.016,0,0);updateCamera();$('.live-tag').innerHTML=studio.hdrReady?'<i></i> STUDIO · HDR 1K':'<i></i> STUDIO 3D';$('#loading').style.display='none';requestAnimationFrame(animate);
canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();$('#loading').style.display='flex';$('#loading').innerHTML='<strong>Przerwano widok 3D.</strong><p>Odśwież plik. Notatki pozostają w przeglądarce.</p>';});
window.sedanLab={getState:()=>({...state,seed,engine:{...model.globals}}),getInfo:()=>({parts:parts.length,moving:parts.filter(p=>p.motion).length,registered:Object.keys(model.registry).length,meshes:model.meshes.length,triangles:renderer.info.render.triangles,hdr:studio.hdrReady}),selectPart,setMode};
